"use client";

import { useEffect, useCallback } from "react";
import {
  getAttribution,
  recordAffiliateClick,
  recordAffiliateImpression,
  recordConversion as recordAffiliateConversion,
  clearAttribution,
  hasTrackingOptOut,
  buildAffiliateUrl,
  parseUtmParams,
  extractAffiliateId,
  AttributionData,
  AffiliateEventType,
} from "@/lib/affiliate-tracking";

interface UseAffiliateOptions {
  toolSlug?: string;
  toolName?: string;
  affiliateId?: string;
  autoTrack?: boolean;
  autoTrackImpressions?: boolean;
}

interface UseAffiliateReturn {
  attribution: AttributionData | null;
  recordClick: (options?: {
    source?: string;
    medium?: string;
    campaign?: string;
    content?: string;
    term?: string;
    position?: string;
  }) => void;
  recordImpression: (position?: string) => void;
  recordConversion: (options: {
    conversionType: "signup" | "purchase" | "trial" | "upgrade";
    value?: number;
    currency?: string;
  }) => void;
  clearTracking: () => void;
  isOptedOut: boolean;
  buildUrl: (baseUrl: string, options?: {
    source?: string;
    medium?: string;
    campaign?: string;
    content?: string;
    term?: string;
  }) => string;
}

export function useAffiliate(options: UseAffiliateOptions = {}): UseAffiliateReturn {
  const {
    toolSlug,
    toolName,
    affiliateId,
    autoTrack = false,
    autoTrackImpressions = false,
  } = options;

  // Get current attribution
  const attribution = getAttribution();

  // Check for opt-out
  const isOptedOut = hasTrackingOptOut();

  // Record a click
  const recordClick = useCallback(
    (clickOptions?: {
      source?: string;
      medium?: string;
      campaign?: string;
      content?: string;
      term?: string;
      position?: string;
    }) => {
      if (isOptedOut || !toolSlug) return;

      const id = affiliateId || extractAffiliateId(window.location.href) || "unknown";

      recordAffiliateClick({
        toolSlug,
        toolName: toolName || "",
        affiliateId: id,
        source: clickOptions?.source || "direct",
        medium: clickOptions?.medium || "referral",
        campaign: clickOptions?.campaign || "",
        content: clickOptions?.content,
        term: clickOptions?.term,
        pageUrl: window.location.href,
        position: clickOptions?.position,
      });
    },
    [toolSlug, toolName, affiliateId, isOptedOut]
  );

  // Record an impression
  const recordImpression = useCallback(
    (position?: string) => {
      if (isOptedOut || !toolSlug || !toolName) return;

      const id = affiliateId || extractAffiliateId(window.location.href) || "unknown";

      recordAffiliateImpression(toolSlug, toolName, id, position);
    },
    [toolSlug, toolName, affiliateId, isOptedOut]
  );

  // Record a conversion
  const recordConversion = useCallback(
    (conversionOptions: {
      conversionType: "signup" | "purchase" | "trial" | "upgrade";
      value?: number;
      currency?: string;
    }) => {
      if (isOptedOut || !toolSlug) return;

      const attr = attribution;
      const id = affiliateId || attr?.affiliateId || "direct";

      recordAffiliateConversion({
        affiliateId: id,
        toolSlug,
        conversionType: conversionOptions.conversionType,
        value: conversionOptions.value,
        currency: conversionOptions.currency,
        attributionModel: attr ? "last_touch" : "direct",
        attributedAffiliateId: id,
      });
    },
    [toolSlug, affiliateId, attribution, isOptedOut]
  );

  // Clear all tracking data
  const clearTracking = useCallback(() => {
    clearAttribution();
  }, []);

  // Build a tracked URL
  const buildUrl = useCallback(
    (baseUrl: string, urlOptions?: {
      source?: string;
      medium?: string;
      campaign?: string;
      content?: string;
      term?: string;
    }) => {
      const id = affiliateId || attribution?.affiliateId || "unknown";

      return buildAffiliateUrl(baseUrl, {
        affiliateId: id,
        source: urlOptions?.source || "affiliate",
        medium: urlOptions?.medium || "referral",
        campaign: urlOptions?.campaign || "",
        content: urlOptions?.content,
        term: urlOptions?.term,
      });
    },
    [affiliateId, attribution]
  );

  // Auto-track clicks on tracked links
  useEffect(() => {
    if (!autoTrack) return;

    const handleClick = (event: MouseEvent) => {
      const target = event.target as HTMLElement;
      const link = target.closest("a[data-affiliate-id]") as HTMLAnchorElement | null;

      if (link) {
        recordClick({
          position: link.dataset.position,
        });
      }
    };

    document.addEventListener("click", handleClick);
    return () => document.removeEventListener("click", handleClick);
  }, [autoTrack, recordClick]);

  // Auto-track impressions
  useEffect(() => {
    if (!autoTrackImpressions || !toolSlug || !toolName) return;

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            const element = entry.target as HTMLElement;
            const position = element.dataset.position || "unknown";
            recordImpression(position);
            observer.unobserve(element);
          }
        });
      },
      { threshold: 0.5 }
    );

    // Observe all affiliate-tracked elements
    document.querySelectorAll("[data-affiliate-id]").forEach((el) => {
      observer.observe(el);
    });

    return () => observer.disconnect();
  }, [autoTrackImpressions, toolSlug, toolName, recordImpression]);

  return {
    attribution,
    recordClick,
    recordImpression,
    recordConversion,
    clearTracking,
    isOptedOut,
    buildUrl,
  };
}

/**
 * Hook for tracking specific affiliate events
 */
export function useAffiliateEvent(
  eventType: AffiliateEventType,
  data?: Record<string, string | number | boolean>
) {
  const handleEvent = useCallback(() => {
    if (hasTrackingOptOut()) return;

    // Dispatch custom event for tracking
    if (typeof window !== "undefined") {
      window.dispatchEvent(
        new CustomEvent(`affiliate:${eventType}`, {
          detail: data,
        })
      );
    }
  }, [eventType, data]);

  return { handleEvent, eventType };
}

/**
 * Hook for reading URL tracking parameters
 */
export function useAffiliateParams() {
  useEffect(() => {
    if (typeof window === "undefined") return null;

    const params = parseUtmParams(window.location.href);
    const affiliateId = extractAffiliateId(window.location.href);

    return {
      ...params,
      affiliateId,
      hasTracking: !!(params.utm_source || affiliateId),
    };
  }, []);
}

import fs from 'fs';
import path from 'path';
import matter from 'gray-matter';
import { unstable_cache } from 'next/cache';

const toolsDirectory = path.join(process.cwd(), 'content/tools');

export interface ToolMetadata {
  title: string;
  slug: string;
  category: string;
  description: string;
  rating: number;
  rating_breakdown?: Record<string, number>;
  image?: string;
  pros?: string[];
  cons?: string[];
  affiliate_link: string;
  promoted?: boolean;
  featured?: boolean;
  sponsored?: boolean;
  tool_of_the_week?: boolean;
  last_updated?: string;
  verified?: boolean;
  discount?: string;
  // Advanced search fields
  pricing?: 'free' | 'freemium' | 'paid' | 'contact';
  price?: string;
  platform?: ('Web' | 'Mobile' | 'Desktop')[];
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  [key: string]: any;
}

export interface Tool {
  metadata: ToolMetadata;
  content: string;
}

const _getAllTools = async (locale: string = 'en'): Promise<ToolMetadata[]> => {
  const enDirectory = path.join(toolsDirectory, 'en');
  // Ensure directory exists
  if (!fs.existsSync(enDirectory)) {
    return [];
  }

  const fileNames = fs.readdirSync(enDirectory);
  const allToolsData = fileNames.map((fileName) => {
    // Remove ".md" from file name to get id
    const id = fileName.replace(/\.md$/, '');

    // Try to find the file in the requested locale
    let fullPath = path.join(toolsDirectory, locale, fileName);

    // Fallback to English if file doesn't exist in requested locale
    if (!fs.existsSync(fullPath)) {
        fullPath = path.join(toolsDirectory, 'en', fileName);
    }

    const fileContents = fs.readFileSync(fullPath, 'utf8');

    // Use gray-matter to parse the post metadata section
    const matterResult = matter(fileContents);

    // Combine the data with the id
    return {
      slug: id,
      ...matterResult.data,
    } as ToolMetadata;
  });

  return allToolsData;
};

export const getAllTools = unstable_cache(
  _getAllTools,
  ['tools-all'],
  { tags: ['tools'], revalidate: 3600 }
);

const _getToolBySlug = async (slug: string, locale: string = 'en'): Promise<Tool | null> => {
  let fullPath = path.join(toolsDirectory, locale, `${slug}.md`);

  // Fallback to English
  if (!fs.existsSync(fullPath)) {
    fullPath = path.join(toolsDirectory, 'en', `${slug}.md`);
  }

  if (!fs.existsSync(fullPath)) {
    return null;
  }

  const fileContents = fs.readFileSync(fullPath, 'utf8');
  const matterResult = matter(fileContents);

  return {
    metadata: {
      slug,
      ...matterResult.data,
    } as ToolMetadata,
    content: matterResult.content,
  };
};

export const getToolBySlug = unstable_cache(
  _getToolBySlug,
  ['tool-slug'],
  { tags: ['tools'], revalidate: 3600 }
);

const _getToolOfTheWeek = async (locale: string = 'en'): Promise<ToolMetadata | null> => {
  const tools = await getAllTools(locale);
  return tools.find((tool) => tool.tool_of_the_week) || null;
}

export const getToolOfTheWeek = unstable_cache(
  _getToolOfTheWeek,
  ['tool-of-the-week'],
  { tags: ['tools'], revalidate: 3600 }
);

export function getToolSlugs() {
  const locales = ['en', 'ja'];
  const allParams: { slug: string; locale: string }[] = [];

  locales.forEach((locale) => {
    const dir = path.join(toolsDirectory, locale);
    if (fs.existsSync(dir)) {
      const fileNames = fs.readdirSync(dir);
      fileNames.forEach((fileName) => {
        if (fileName.endsWith('.md')) {
          allParams.push({
            slug: fileName.replace(/\.md$/, ''),
            locale: locale,
          });
        }
      });
    }
  });

  return allParams;
}

const _getRelatedTools = async (currentTool: ToolMetadata, limit: number = 3, locale: string = 'en'): Promise<ToolMetadata[]> => {
  const allTools = await getAllTools(locale);
  const candidates = allTools.filter(
    (tool) => tool.category === currentTool.category && tool.slug !== currentTool.slug
  );

  // Shuffle the candidates array
  for (let i = candidates.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [candidates[i], candidates[j]] = [candidates[j], candidates[i]];
  }

  return candidates.slice(0, limit);
}

export const getRelatedTools = unstable_cache(
  _getRelatedTools,
  ['related-tools'],
  { tags: ['tools'], revalidate: 3600 }
);

