            {formatTimeAgo(tool.viewedAt)}
          </p>
        </div>
        <button
          onClick={(e) => {
            e.preventDefault();
            onRemove();
          }}
          className="opacity-0 group-hover:opacity-100 p-1 text-zinc-400 hover:text-red-500 transition-all"
          aria-label={t('remove')}
        >
          <X className="h-4 w-4" />
